package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_join_TriageGen0Test {

    @Test
    public void testJoin_ArrayNull() {
        assertNull(StringUtils.join(null, ",", 0, 1));
    }

    @Test
    public void testJoin_SeparatorNull() {
        Object[] array = {"A", "B", "C"};
        // If separator is null, it should default to EMPTY (which is "")
        assertEquals("ABC", StringUtils.join(array, null, 0, 3));
    }

    @Test
    public void testJoin_NoOfItemsZeroOrNegative() {
        Object[] array = {"A", "B", "C"};
        // endIndex == startIndex
        assertEquals("", StringUtils.join(array, ",", 1, 1));
        // endIndex < startIndex
        assertEquals("", StringUtils.join(array, ",", 2, 1));
    }

    @Test
    public void testJoin_NormalCase() {
        Object[] array = {"A", "B", "C", "D"};
        assertEquals("A,B,C", StringUtils.join(array, ",", 0, 3));
        assertEquals("B-C", StringUtils.join(array, "-", 1, 3));
    }

    @Test
    public void testJoin_SingleElement() {
        Object[] array = {"A", "B", "C"};
        assertEquals("A", StringUtils.join(array, ",", 0, 1));
        assertEquals("B", StringUtils.join(array, ",", 1, 2));
    }

    @Test
    public void testJoin_WithNullElements() {
        Object[] array = {"A", null, "C"};
        // The logic: if (array[i] != null) { buf.append(array[i]); }
        // If null, it simply skips appending the content but the separator logic still applies
        // For i=0: append "A"
        // For i=1: i > startIndex is true, append separator ",", array[1] is null, nothing appended
        // For i=2: i > startIndex is true, append separator ",", append "C"
        assertEquals("A,,C", StringUtils.join(array, ",", 0, 3));

        Object[] array2 = {null, "B", null};
        assertEquals(",B,", StringUtils.join(array2, ",", 0, 3));
    }

    @Test
    public void testJoin_WithFirstElementNull() {
        // Tests the StringBuilder initialization branch: (array[startIndex] == null ? 16 : ...)
        Object[] array = {null, "B"};
        assertEquals(",B", StringUtils.join(array, ",", 0, 2));
    }

    @Test
    public void testJoin_NonStringObjects() {
        Object[] array = {1, 2, 3};
        assertEquals("1,2,3", StringUtils.join(array, ",", 0, 3));
    }

    @Test
    public void testJoin_EmptySeparator() {
        Object[] array = {"A", "B", "C"};
        assertEquals("ABC", StringUtils.join(array, "", 0, 3));
    }
}
